final_sources.budget.py:
"""Retry-budget accounting for the ingest scheduler."""


class RetryBudget:
    """Tracks how many retries remain for a job.

    `consume` spends one retry and returns True when the spend was allowed.
    Once the budget is exhausted, further calls return False and must not push
    `remaining` below zero.
    """

    def __init__(self, limit):
        self.limit = limit
        self.used = 0

    @property
    def remaining(self):
        return self.limit - self.used

    def consume(self):
        if self.remaining > 0:
            self.used += 1
            return True
        return False

    def reset(self):
        self.used = 0

final_sources.queue_impl.py:
"""In-memory job queue with priority ordering."""

import heapq
import itertools


class JobQueue:
    """A priority queue of jobs.

    Lower `priority` values are dequeued first. Jobs pushed with equal priority
    come out in the order they were pushed (FIFO within a priority).
    """

    def __init__(self):
        self._heap = []
        self._counter = itertools.count()

    def push(self, job, priority=5):
        heapq.heappush(self._heap, (priority, next(self._counter), job))

    def pop(self):
        if not self._heap:
            return None
        _, _, job = heapq.heappop(self._heap)
        return job

    def __len__(self):
        return len(self._heap)

final_sources.cache.py:
"""A tiny TTL cache used by the metrics collector."""

from collections import OrderedDict


class TTLCache:
    """Mapping with per-entry expiry.

    `clock` is a zero-argument callable returning a monotonic float, injected so
    tests can control time.
    """

    def __init__(self, ttl, clock, max_size=None):
        self.ttl = ttl
        self.clock = clock
        self.max_size = max_size
        self._data = OrderedDict()

    def set(self, key, value):
        if key in self._data:
            self._data[key] = (value, self.clock())
            self._data.move_to_end(key)
        else:
            self._data[key] = (value, self.clock())

        if self.max_size is not None and len(self._data) > self.max_size:
            self._data.popitem(last=False)

    def get(self, key, default=None):
        entry = self._data.get(key)
        if entry is None:
            return default
        value, stamp = entry
        if self.clock() - stamp >= self.ttl:
            del self._data[key]
            return default
        self._data.move_to_end(key)
        return value

    def __len__(self):
        return len(self._data)

final_sources.router.py:
"""Minimal path router for the internal status service."""


class Router:
    """Maps URL paths to handlers.

    Routes are registered with `add`, and `resolve` returns (handler, params)
    for a path or (None, {}) when nothing matches.
    """

    def __init__(self):
        self._routes = []

    def add(self, path, handler):
        self._routes.append((path, handler))

    def resolve(self, path):
        # 1. Static match first (wins over dynamic regardless of order)
        for route, handler in self._routes:
            if route == path:
                return handler, {}

        # 2. Dynamic match
        path_segments = path.split('/')
        for route, handler in self._routes:
            if '<' not in route or '>' not in route:
                continue

            route_segments = route.split('/')
            if len(route_segments) != len(path_segments):
                continue

            params = {}
            match = True
            for r_seg, p_seg in zip(route_segments, path_segments):
                if r_seg.startswith('<') and r_seg.endswith('>'):
                    # It's a parameter
                    param_name = r_seg[1:-1]
                    if p_seg == '':  # An empty segment must not satisfy a parameter
                        match = False
                        break
                    params[param_name] = p_seg
                elif r_seg != p_seg:
                    match = False
                    break

            if match:
                return handler, params

        return None, {}
